package com.nextrade.engine.matching; import com.nextrade.domain.order.Order; import com.nextrade.common.valueobject.*; import java.util.*; public final class FokLiquidityCheck {private FokLiquidityCheck(){} public static boolean canFill(Order incoming,NavigableMap<Price,? extends java.util.Collection<Order>> levels){Quantity remaining=incoming.remaining();for(var e:levels.entrySet()){if(!incoming.marketableAgainst(e.getKey()))break;for(Order o:e.getValue()){if(o.status().isTerminal())continue;remaining=remaining.min(remaining).subtract(remaining.min(o.remaining()));if(remaining.isZero())return true;}}return remaining.isZero();}}
